-- data/sets_forever.lua (generated by tools/update-sets.ps1 -Forever, nazumods/wow#989) is loaded for real,
-- under both clients: it must leave Retail's tables alone and replace them on Forever only. The generator itself
-- is tested by Tooling/tests/update-sets-forever.test.ps1; this proves the file it wrote behaves.

describe("Warbandeer_Collected data/sets_forever.lua", function()
  local function load(isForever)
    local retailSets, retailPtr, retailBuild = { { id = 1 } }, { { id = 2 } }, { live = "12.1.5.70391", ptr = "12.1.5.70391" }
    local ns = {
      flavor = { isForever = isForever, isRetail = not isForever },
      Sets = retailSets, PtrSets = retailPtr, PtrBuild = retailBuild,
    }
    assert(loadfile("Warbandeer_Collected/data/sets_forever.lua"))("Warbandeer_Collected", ns)
    return ns, retailSets, retailPtr, retailBuild
  end

  it("Retail: leaves ns.Sets and ns.PtrSets as they were", function()
    local ns, sets, ptr, build = load(false)
    assert.equals(sets, ns.Sets)
    assert.equals(ptr, ns.PtrSets)
    assert.equals(build, ns.PtrBuild)
    assert.same({ { id = 1 } }, ns.Sets)
  end)

  it("a client with no flavor table at all is left alone too", function()
    local sets = { { id = 1 } }
    local ns = { Sets = sets, PtrSets = {} }
    assert(loadfile("Warbandeer_Collected/data/sets_forever.lua"))("Warbandeer_Collected", ns)
    assert.equals(sets, ns.Sets)
  end)

  it("Forever: replaces ns.Sets with Forever's sets and empties ns.PtrSets", function()
    local ns, sets, ptr = load(true)
    assert.not_equals(sets, ns.Sets)
    assert.not_equals(ptr, ns.PtrSets)
    assert.same({}, ns.PtrSets)
    assert.is_nil(ns.PtrBuild)
    assert.equals(7, #ns.Sets)
    local ids = {}
    for _, row in ipairs(ns.Sets) do ids[#ids + 1] = row.id end
    assert.same({ 3634, 4397, 5700, 5701, 5702, 5703, 5914 }, ids)
  end)

  it("Forever: every row is well formed", function()
    local ns = load(true)
    for _, row in ipairs(ns.Sets) do
      assert.is_number(row.id)
      assert.is_string(row.name)
      assert.is_true(row.release >= 1 and row.release <= 12, "release " .. tostring(row.release))
      assert.equals("World", row.category)
      assert.is_true(row.allClasses)
      assert.equals(13, #row.sets)
      for index, cell in ipairs(row.sets) do
        assert.equals(row.id, cell.id)
        assert.equals(row.name, cell.name)
        assert.equals(index, cell.classId)
      end
    end
  end)

  it("Forever: the generated releases are ExpansionID + 1 (Shen'dorei 1, Snugglefin 10, Spiritplume 11)", function()
    local ns = load(true)
    local release = {}
    for _, row in ipairs(ns.Sets) do release[row.id] = row.release end
    assert.equals(1, release[5700])
    assert.equals(10, release[3634])
    assert.equals(11, release[4397])
  end)
end)
